"""Presentation-only mission-control skin. No remote fonts, assets or services."""
CSS = """
:root{--bg:#0b1019;--panel:#121a27;--line:#2a3548;--fg:#edf2fc;--dim:#a5b2c8;--gold:#c5b4ff;--red:#ffaaa9;--green:#82e4cf;--blue:#a8c8ff;--accent:#b39cff}
body{background:radial-gradient(ellipse at 55% 0,#1b2241 0,transparent 48%),var(--bg);font-size:14px}
.sidebar{background:#0e1420;border-color:#263045}.sidebar nav a{color:#b2bfd4;border-radius:9px}.sidebar nav a[aria-current]{background:#252340;color:#ded5ff;box-shadow:inset 3px 0 #b39cff}.sidebar nav a:hover{background:#1b2537}.sidebar-foot{line-height:1.8}.brand-mark{background:#30294c;color:#ded1ff}.workspace-label{margin:24px 0}.wordmark{letter-spacing:-1.3px}
header{padding-top:30px;padding-bottom:24px}header h1{font-size:30px;font-weight:650}.workspace{gap:24px}main{gap:20px}section{border-radius:16px;padding:22px;background:linear-gradient(135deg,#172031,#121a27);box-shadow:0 8px 24px #00000014}h2{font-size:17px}.eyebrow{letter-spacing:.12em}.pill{border-radius:20px;padding:5px 10px}.pill.warn{background:#28243d;border-color:#4c4266}.pill.ok{background:#183632;border-color:#315b52}.hero{background:linear-gradient(115deg,#212841,#152735 70%,#14252f);border-color:#3b4661}.hero-title{font-size:26px;font-weight:600}.hero .metrics{margin:18px 0 12px}.metric,.metric:nth-child(n){background:#0e172780;border-color:#364257;border-radius:12px;padding:12px 14px}.metric strong{font-size:26px;letter-spacing:-.04em}.metric span{color:#b9c7da}.next-action{border-color:#3b4960;padding-top:16px}.next-action .eyebrow{color:#ccbdff}.next-action strong{font-size:16px}.notice{background:#172032;border-color:#344057;border-radius:12px}.agent-tab{border-radius:20px}.agent-filter:checked+label{background:#2d2945;border-color:#665484;color:#e4dcff}
.agent-summary{background:#121b2a;border-radius:12px;box-shadow:none;padding:14px}.avatar-stage{background:#28314a}.agent-summary .role{font-size:11px}.talk-button{color:#c9c7ed}.chat-dock{background:linear-gradient(165deg,#1a2033,#101a28);border-color:#3b405c;border-radius:18px;box-shadow:0 12px 40px #0002}.chat-heading h2{font-size:20px}.chat-heading p,.chat-snapshot,.chat-privacy{font-size:11px}.chat-jump{background:#26243d;border-color:#514665;border-radius:20px}.composer{background:#0d1420;border-radius:12px}.composer button{background:#c4b2ff}.prompt-chip,#chat-agent{background:#20283c;border-color:#3f4863;border-radius:8px}.nova-button{background:#302842;border-color:#5b4871}.chat-persona img{background:#30314b}.empty,pre{background:#0c1422;border-color:#2e3b51;border-radius:10px}.empty:before{color:#8c82ae}td,th{padding:12px 9px}tbody tr:hover{background:#222c40}details>summary{font-size:12px}footer{line-height:1.8}
/* The canvas is always visible first; deep evidence stays in native disclosures. */
.desk-module{background:radial-gradient(ellipse at 50% 38%,#25294880,transparent 65%),#111a29;border-color:#44425f;border-radius:20px;padding:0 24px;box-shadow:0 18px 60px #0003,inset 0 1px #ddd8ff0c;overflow:hidden}.desk-launch{padding:24px 0 12px}.desk-launch strong{font-size:25px;font-weight:650;margin-top:4px}.desk-launch:after{font-size:20px}.desk-record-badge{margin-left:auto;border:1px solid #554969;border-radius:20px;padding:6px 10px;color:#d1c3fa;background:#29243f;font-size:9px;letter-spacing:.1em}.desk-intro{border:0;padding:0;margin:0 0 22px;font-size:13px}.desk-brief{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:18px 20px;background:#0c152580;border:1px solid #35415b;border-radius:14px}.desk-brief h3{font-size:21px;font-weight:550;margin:4px 0}.desk-brief p{font-size:12px;color:var(--dim);max-width:55ch}.desk-progress{flex:0 0 145px;display:flex;flex-direction:column;gap:5px}.desk-progress strong{font-size:24px;letter-spacing:-.04em;color:var(--green)}.desk-progress span{font-size:10px;color:var(--dim)}.desk-progress meter{width:100%;height:12px;accent-color:var(--green)}meter::-webkit-meter-bar{background:#29364c;border:0}meter::-webkit-meter-optimum-value{background:linear-gradient(90deg,#8f89ea,#80e0d0)}
.desk-toolbar{gap:8px;margin-top:20px}.desk-toolbar label{font-size:11px}.desk-toolbar select,.desk-toolbar button{border-radius:9px;background:#1e2940;border-color:#465273;padding:10px;font-size:11px;min-height:38px}.desk-toolbar select{color:#e1eafa}.desk-toolbar button:hover{background:#303752;border-color:#9a8ac4}#desk-replay{background:#c4b2ff;color:#1b1730;border-color:#c4b2ff;font-weight:650}#desk-motion[aria-pressed=true]{background:#322947;border-color:#a190c9}.desk-replay-status{font-size:11px;color:#c9b9fc;min-height:18px}#desk-connection{font-size:11px;color:#a8c8ff}#desk-freshness{line-height:1.6}#desk-cycle-title{font-size:10px;color:#aebbd1;padding:8px 0;border-top:1px solid #303b52}.desk-metadata{font-size:11px}.desk-metadata summary{padding:4px 0}.desk-warnings:empty{display:none}
.desk-flow{gap:12px;margin:16px 0 12px;counter-reset:stage;padding-bottom:4px}.desk-flow li{counter-increment:stage;min-width:126px;padding:12px 10px 10px;background:#101a2c;border-color:#35415c;border-radius:10px;margin:0}.desk-flow li strong{font-size:11px;line-height:1.5}.desk-flow li strong:before{content:'0' counter(stage);display:block;color:#bac5df;font-size:9px;letter-spacing:.12em;margin-bottom:6px}.desk-flow li span{font-size:10px}.desk-flow li:not(:last-child):after{right:-13px;top:24px;font-size:18px}.desk-flow li.signal>span:last-child:after{top:34px}.desk-flow li:before{height:3px}.desk-legend{font-size:10px;line-height:1.7}.desk-flow li.lit{box-shadow:0 0 20px color-mix(in srgb,var(--tone) 10%,transparent)}
.desk-swarm{grid-template-rows:140px 120px 140px;gap:10px;margin:26px 0 14px;border-radius:18px;background:radial-gradient(ellipse at center,#7163b329,transparent 65%),radial-gradient(#798bb21f .7px,transparent .8px);background-size:auto,18px 18px}.desk-agent{position:relative;overflow:hidden;justify-content:flex-start;background:linear-gradient(140deg,#26304a,#172135 80%);border-color:#53607b;border-radius:14px;padding:16px;gap:4px;box-shadow:0 6px 18px #0003;color:var(--fg)}.desk-agent:hover,.desk-agent[aria-pressed=true]{background:linear-gradient(140deg,#35304f,#202b42);border-color:#c5b4ff;transform:translateY(-2px)}.desk-agent strong{font-size:14px;letter-spacing:-.02em;line-height:1.4;padding-right:20px}.desk-role{font-size:9px;color:#b9c7df;letter-spacing:.1em}.desk-node-icon{position:absolute;right:12px;top:12px;display:grid;place-items:center;width:26px;height:26px;border-radius:8px;background:#bbb1ff19;color:#ded5ff;font-size:20px}.desk-task{font-size:11px;line-height:1.5;color:#c0cce0;margin:4px 0;max-width:95%}.desk-state{font:10px/1.4 'Segoe UI',sans-serif;color:var(--tone);border:1px solid color-mix(in srgb,var(--tone) 40%,transparent);background:color-mix(in srgb,var(--tone) 8%,transparent);padding:3px 7px;border-radius:20px;align-self:flex-start}.desk-card-hint{font-size:9px;color:#aebcda;margin-top:auto}.desk-agent[data-status=not_implemented]{background:#121c2b;border-color:#3f4961;box-shadow:none}.desk-agent[data-status=not_implemented] .desk-node-icon{color:#a1a9c4;background:#252e41}.desk-agent[data-status=not_implemented] .desk-state{color:#b5bed2;border-color:#45516a;background:#222c3e}.desk-agent.lit{box-shadow:0 0 26px color-mix(in srgb,var(--tone) 12%,transparent),inset 0 1px #ffffff12}.desk-agent[data-status=not_implemented].lit{box-shadow:none;border-color:#45516a}
.desk-core{position:relative;z-index:1;min-width:185px;border-radius:40px;background:linear-gradient(135deg,#343254,#1c2c42);border-color:#78759d;box-shadow:0 0 0 8px #9d8fd508,0 0 0 18px #9d8fd505;padding:14px 24px;gap:3px}.desk-core .eyebrow{font-size:9px;color:#d0c5ed}.desk-core strong{font-size:15px}.desk-core small{color:#b6c3dc}.desk-connectors{opacity:1}.desk-connectors path{stroke:#697693;stroke-width:1.3}.desk-connectors path[data-link=prior],.desk-connectors path[data-link=edge]{stroke:#47536b;stroke-dasharray:3 7}.desk-connectors path.lit{stroke-width:2;filter:drop-shadow(0 0 5px var(--tone))}.desk-swarm.flowing .desk-connectors path.lit{animation:none;stroke-dasharray:none}.desk-swarm.flowing .desk-connectors path.lit[data-tone=pass]{stroke-dasharray:9 18;animation:desk-dash 1.4s linear infinite}.desk-connectors path[data-link=prior].lit,.desk-connectors path[data-link=edge].lit{stroke:#47536b;filter:none;stroke-width:1;stroke-dasharray:3 7}.desk-link-legend{display:flex;gap:16px;flex-wrap:wrap;color:#b2bfd9;font-size:10px}.desk-link-legend span:first-child{color:var(--green)}#desk-inspector{background:#0e1829;border-color:#3a4763;border-radius:14px;padding:20px;margin:20px 0}#desk-inspector>h3{font-size:17px}#desk-inspector>p{color:#bac9df;line-height:1.8}#desk-inspector details{margin-top:14px}#desk-proposals h3,#desk-activity h3{font-size:15px;margin:22px 0 12px}.desk-activity-item summary{justify-content:flex-start;gap:16px;align-items:center}.desk-activity-item summary:before{content:'◇';color:#c5b4ff;font-size:18px}.desk-activity-item summary span{margin-left:auto;font-size:11px}.desk-proposal,.desk-activity-item{padding:8px 0;border-color:#303d55}.desk-evidence{margin-top:18px}.desk-limitations{padding-top:14px;line-height:1.8}.desk-empty{background:#101a2b;border-color:#42516c;border-radius:10px}
.desk-agent:disabled{opacity:1;cursor:default}.desk-agent:disabled:hover{transform:none}
#agent-desk[data-motion=paused] *,#agent-desk[data-motion=paused] *:before,#agent-desk[data-motion=paused] *:after{animation:none!important;transition:none!important}
@media(min-width:1400px){.desk-swarm{grid-template-rows:158px 104px 158px}.desk-task{font-size:12px}.desk-agent strong{font-size:15px}}
@media(max-width:1390px){.desk-module{padding:0 18px}.desk-agent{padding:12px}.desk-task{font-size:10px}.desk-node-icon{width:20px;height:20px;right:8px;top:8px;font-size:16px}.desk-agent strong{font-size:12px}.desk-core{min-width:160px}.desk-record-badge{font-size:8px}.desk-role{font-size:8px}}
@media(max-width:760px){header h1{font-size:26px}main{gap:16px}.hero-title{font-size:23px}.desk-module{padding:0 14px;border-radius:16px}.desk-launch strong{font-size:23px}.desk-record-badge{max-width:110px;text-align:center;font-size:8px}.desk-brief{padding:14px;gap:14px;align-items:start}.desk-brief h3{font-size:18px}.desk-progress{flex-basis:86px}.desk-progress strong{font-size:21px}.desk-brief p{font-size:11px}.desk-toolbar label{flex-basis:100%}.desk-toolbar button{flex:1;padding:9px 7px;min-height:42px}.desk-swarm{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(3,174px) 106px;gap:12px;margin-top:20px}.desk-core{grid-row:4}.desk-agent{padding:12px}.desk-agent strong{font-size:13px}.desk-task{font-size:11px;max-width:100%}.desk-role{font-size:8px;padding-right:18px}.desk-node-icon{font-size:17px}.desk-link-legend{gap:6px 14px}.desk-flow li{min-width:135px}.desk-connectors{display:none}.desk-agent:after{content:'';position:absolute;height:2px;bottom:0;left:0;right:0;background:var(--tone);opacity:.6}.desk-agent[data-status=not_implemented]:after{display:none}#desk-inspector{padding:16px}.desk-activity-item summary{gap:8px}.desk-activity-item summary strong{font-size:11px;max-width:65%}.desk-activity-item summary span{font-size:10px}.metrics{gap:8px}.metric strong{font-size:24px}.metric span{font-size:10px}.chat-jump{padding:8px 10px}}
@media(prefers-reduced-motion:reduce){.desk-agent:hover{transform:none}}
"""
